sys_script_client.script:
function onLoad() {
    // Check if case_id is available
    var case_id = g_form.getValue('case_id');
    if (!case_id) {
        g_form.addErrorMessage('Case ID not found on the form.');
        return;
    }

    // Use GlideAjax to fetch the latest decision record
    var ga = new GlideAjax('x_rptp_kotak.KotakUWWorkbench');
    ga.addParam('sysparm_name', 'fetchLatestDecisionRecord');
    ga.addParam('sysparm_case_id', case_id);
	//alert(case_id)

    ga.getXMLAnswer(function(response) {
        var result = response.responseXML.documentElement.getAttribute("answer");
		alert(result)
        if (result) {

            var recordData = JSON.parse(result);

            // Populate form fields if they exist
            if (g_form.hasField('emr_decision')) g_form.setValue('emr_decision', recordData.emr_decision);
            if (g_form.hasField('per_millie')) g_form.setValue('per_millie', recordData.per_millie);
            if (g_form.hasField('remarks')) g_form.setValue('remarks', recordData.remarks);
            if (g_form.hasField('emr')) g_form.setValue('emr', recordData.emr);
            if (g_form.hasField('reason')) g_form.setValue('reason', recordData.reason);
            if (g_form.hasField('final_remarks')) g_form.setValue('final_remarks', recordData.final_remarks);
            if (g_form.hasField('reduced_cover_term')) g_form.setValue('reduced_cover_term', recordData.reduced_cover_term);
            if (g_form.hasField('comments')) g_form.setValue('comments', recordData.comments);
            if (g_form.hasField('hold_internal_requirement')) g_form.setValue('hold_internal_requirement', recordData.hold_internal_requirement);
            if (g_form.hasField('reduced_sum_assured')) g_form.setValue('reduced_sum_assured', recordData.reduced_sum_assured);
        } else {
            console.log('No record data returned for case ID: ' + case_id);
        }
    });
}
